        IPackageFragmentRoot root = (IPackageFragmentRoot) element.getAncestor(IJavaElement.PACKAGE_FRAGMENT_ROOT);
        if (root != null) {
            boolean isBinary = root.exists() && root.getKind() == IPackageFragmentRoot.K_BINARY;
