package test;

import org.eclipse.jdt.core.IJavaElement;
import org.eclipse.jdt.core.IPackageFragmentRoot;
import org.eclipse.jdt.core.JavaModelException;

public class TestClass {
    public void foo(IJavaElement element) throws JavaModelException {
        IPackageFragmentRoot root = (IPackageFragmentRoot) element.getAncestor(IJavaElement.PACKAGE_FRAGMENT_ROOT);
        if (root != null) {
            boolean isSource = root.getKind() == IPackageFragmentRoot.K_SOURCE; // Different constant
            System.out.println(isSource);

            Object someOtherObject = new Object();
            boolean isSomething = someOtherObject.equals("test"); // Not IPackageFragmentRoot
            System.out.println(isSomething);
        }
    }
}
